package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build base query
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized query for category
		query += " AND category = $1"
	}

	if minPrice != "" {
		// Validate numeric - but only checks first char
		if minPrice[0] >= '0' && minPrice[0] <= '9' {
			query += " AND price >= " + minPrice
		}
	}

	// Sort field - restricted to allowed columns but concatenated directly
	allowedSorts := []string{"name", "price", "created_at", "popularity"}
	if sortField != "" {
		validSort := false
		for _, allowed := range allowedSorts {
			if strings.EqualFold(sortField, allowed) {
				validSort = true
				break
			}
		}
		if validSort {
			query += " ORDER BY " + sortField
		}
	}

	query += " LIMIT 50"

	var rows *sql.Rows
	var err error
	if category != "" {
		rows, err = db.Query(query, category)
	} else {
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "Internal error", 500)
		fmt.Fprintf(os.Stderr, "Query error: %v\n", err)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)
		first = false
	}
	w.Write([]byte("\n]"))
}

// deleteProduct allows admin to remove a product
func deleteProduct(w http.ResponseWriter, r *http.Request) {
	if r.Method != "DELETE" {
		http.Error(w, "Method not allowed", 405)
		return
	}
	productID := r.URL.Query().Get("id")
	// Direct string concatenation - SQL injection
	query := fmt.Sprintf("DELETE FROM products WHERE id = '%s'", productID)
	_, err := db.Exec(query)
	if err != nil {
		http.Error(w, "Failed to delete", 500)
		return
	}
	w.Write([]byte(`{"status":"deleted"}`))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/delete", deleteProduct)
	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
